const DICTS = { en, hi, te, es, fr, ar };

/* Translate outside React (used by the demo backend). */
export const translate = (lang, key, vars) => {
  let s = DICTS[lang]?.[key] ?? en[key] ?? key;
  if (vars) Object.entries(vars).forEach(([k, v]) => (s = s.replace(`{${k}}`, v)));
  return s;
};

export const currentLang = () => localStorage.getItem("lang") || "en";

const Ctx = createContext(null);

export function LanguageProvider({ children }) {
  const [lang, setLang] = useState(() => {
    const saved = localStorage.getItem("lang");
    if (saved && DICTS[saved]) return saved;
    const nav = (navigator.language || "en").slice(0, 2);
    return DICTS[nav] ? nav : "en";
  });

  useEffect(() => {
    localStorage.setItem("lang", lang);
    const meta = LANGUAGES.find((l) => l.code === lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = meta?.rtl ? "rtl" : "ltr";
  }, [lang]);

  const value = useMemo(
    () => ({ lang, setLang, meta: LANGUAGES.find((l) => l.code === lang), t: (k, v) => translate(lang, k, v) }),
    [lang]
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
